  "contacts": [
    {
      "contactId": "8de16b15-0723-5609-917c-df5bc64b9277",
      "name": "George Eliadis",
      "roleLabel": "Economic buyer - Co-Founder & CEO",
      "overview": "George owns Probook as Co-Founder & CEO and previously worked as a contractor at A2Z Exterior Pressure Washing. He is publicly discussing the $40M funding, the move beyond founder-led sales, and his hands-on experience meeting customers, running demos, and visiting shops.",
      "howToOpen": [
        {
          "line": "George, your move from personally running every demo to building beyond founder-led sales stood out.",
          "hook": "Being stuck in founder-led sales isn't a flex. I wish I realized that sooner",
          "sourceUrl": "https://www.linkedin.com/posts/george-eliadis_until-december-our-sales-team-was-just-activity-7441840906384683008-3s7v"
        },
        {
          "line": "George, congratulations on the funding—your experience operating a home-services business gives the raise a clear customer problem behind it.",
          "hook": "Today, we're announcing $40M in funding from Sequoia and Andreessen Horowitz to solve a problem I faced in my own business.",
          "sourceUrl": "https://www.linkedin.com/posts/george-eliadis_today-were-announcing-40m-in-funding-from-activity-7475172924774293504-mVOB"
        }
      ]
    },
    {
      "contactId": "f31ccd75-f376-528f-8b6c-f2f823a60e56",
      "name": "Mark Hoffman",
      "roleLabel": "Economic buyer - Chief Revenue Officer",
      "overview": "Mark owns revenue as Probook’s Chief Revenue Officer, after serving as Chief Sales Officer at Tennr and holding sales leadership roles at VTS, Hightower, and ZocDoc. He is reachable around Probook’s $40M raise and the effort to grow the GTM team, which he said is approaching 20.",
      "howToOpen": [
        {
          "line": "Mark, congratulations on Probook’s $40M raise from Sequoia and Andreessen Horowitz.",
          "hook": "Today is a big day at Probook. We're announcing our $40M raise from Sequoia and Andreessen Horowitz",
          "sourceUrl": "https://www.linkedin.com/posts/mark-hoffman-582a5741_today-is-a-big-day-at-probook-were-announcing-activity-7475232474495725568--2KU"
        },
        {
          "line": "Mark, you mentioned the GTM team is nearing 20 with more hiring ahead—what are you prioritizing as it scales?",
          "hook": "The GTM team is inching up towards 20 now, with many more to go.",
          "sourceUrl": "https://www.linkedin.com/posts/mark-hoffman-582a5741_today-is-a-big-day-at-probook-were-announcing-activity-7475232474495725568--2KU"
        }
      ]
    },
    {
      "contactId": "0c49f3eb-9f51-579b-99f7-6acb965af754",
      "name": "Kate Blumberg",
      "roleLabel": "Champion - Director of Growth",
      "overview": "Kate owns growth at Probook and joined to lead growth and build out the marketing organization. She came from BuildOps, Middesk, SafeGraph, Survata, and Branch, with experience building demand generation engines across inbound, ABM, events, lifecycle, and paid.",
      "howToOpen": [
        {
          "line": "Kate, you joined Probook to lead growth and build the marketing organization—congrats on the new role.",
          "hook": "I’m excited to share that I’ve joined Probook to lead growth and build out the marketing organization",
          "sourceUrl": "https://www.linkedin.com/posts/kibrady12_im-excited-to-share-that-ive-joined-probook-activity-7475235473679077376-nv9z"
        },
        {
          "line": "Kate, your focus on demand generation systems across ABM, events, lifecycle, and paid is directly relevant to Probook’s GTM buildout.",
          "hook": "When I joined BuildOps, it was to join a high-performing, revenue-obsessed team where I could focus on one thing: building a demand generation engine that delivered for sales… hiring and leading a team, scaling programs across inbound, ABM, events, lifecycle, and paid… creating systems, scaling teams, sharpening positioning, and helping turn momentum into revenue.",
          "sourceUrl": "https://www.linkedin.com/posts/kibrady12_after-two-years-at-buildops-i-activity-7459629371444703232-esk_"
        }
      ]
    },
    {
      "contactId": "61006812-713c-5564-8c38-16620cbcc0b3",
      "name": "Aaron Churba",
      "roleLabel": "Champion - Director of Sales & Development",
      "overview": "Aaron owns sales development at Probook and is currently leading a team of five sellers. He came from sales leadership and advisory roles at Bite, Zip Security, and Electric, and is publicly focused on helping more businesses discover Probook and building its GTM organization.",
      "howToOpen": [
        {
          "line": "Aaron, you’re currently leading five sellers at Probook—how are you structuring the team as it grows?",
          "hook": "Currently leading a team of 5 sellers and counting.",
          "sourceUrl": "https://www.linkedin.com/in/aaronloganchurba"
        },
        {
          "line": "Aaron, your focus on helping more businesses discover Probook and building the GTM organization caught my attention.",
          "hook": "helping more businesses discover Probook, building a world-class GTM organization, and contributing to the next stage of growth.",
          "sourceUrl": "https://www.linkedin.com/in/aaronloganchurba"
        }
      ]
    },
    {
      "contactId": "f4ec4553-7a98-5f74-8e61-2e445319374b",
      "name": "Lewis Zhang",
      "roleLabel": "Technical evaluator - Co-Founder / CTO",
      "overview": "Lewis owns the technical evaluation as Probook’s Co-Founder / CTO, after working as a Senior ML Engineer at Roblox and research and engineering roles at Berkeley AI Research, Confluent, Rubrik, Tesla, and Intel. He is publicly focused on scalable data and ML systems, reliable engineering workflows, and sharing technical wins.",
      "howToOpen": [
        {
          "line": "Lewis, your move from Senior ML Engineer at Roblox to Co-Founder / CTO at Probook stood out.",
          "hook": "Co-Founder / CTO @ Probook (2024-01-01..present); Senior ML Engineer @ Roblox (2021-01-01..2024-01-01)",
          "sourceUrl": "https://www.linkedin.com/in/lewisfzhang"
        },
        {
          "line": "Lewis, I saw your note about sharing small wins—what technical milestones are you tracking at Probook?",
          "hook": "I'm certainly not the best writer (way better at math) but I am going to start to be more active on LinkedIn and share the small wins.",
          "sourceUrl": "https://www.linkedin.com/posts/lewisfzhang_im-certainly-not-the-best-writer-way-better-activity-7387118180609085442-UJ-d"
        }
      ]
    }
  ]
